{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "CC-292, an acrylamide-containing pyrimidine aniline inhibitor, showed excellent oral bioavailability in humans; the query shares the acrylamide, pyrimidine, and aniline core, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Golidocitinib, a pyrimidine-indazole inhibitor, had >80% oral bioavailability in healthy participants; the query contains analogous pyrimidine and N-methyl indazole motifs, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Brexpiprazole, containing the same N-methyl indazole moiety as the query, has 95% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Zongertinib, an acrylamide pyrimidine kinase inhibitor, was predicted to have 41% oral bioavailability in humans, above the 20% threshold and supportive for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "GSK1322322, a pyrimidine-containing inhibitor with a basic amine side chain, had 77% absolute oral bioavailability in healthy volunteers after a meal, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Tariquidar, a large lipophilic P-gp substrate with multiple H-bond acceptors, had low oral bioavailability in humans; this is the main contradictory evidence, but its lower similarity and different chemotype limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite an unfavorable physicochemical prior, multiple structurally related kinase inhibitors with shared acrylamide, pyrimidine, and indazole motifs show human oral bioavailability well above 20% (41-95%). The low-bioavailability tariquidar evidence is less transferable. Therefore predict high F (>=20%) with moderate confidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "All analogue similarities are below 0.3, limiting structural transferability.",
    "Solubility, permeability, and first-pass metabolism of the query are not experimentally characterized.",
    "Potential efflux transporter liability is not directly assessed for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

